import type { CreateHost, Host, Message, NodeView, Outcome } from '../host.ts';

const NODE_IDS = ['n0', 'n1', 'n2'];
const MAJORITY = 2;

interface NodeState {
  role: NodeView['role'];
  term: number;
  votedFor: string | null;
  votes: Set<string>;
}

const createHost: CreateHost = async () => {
  const nodes = new Map<string, NodeState>();
  for (const id of NODE_IDS) {
    nodes.set(id, { role: 'follower', term: 0, votedFor: null, votes: new Set() });
  }
  const inTransit = new Map<string, Message>();
  let nextId = 1;

  function send(from: string, to: string, action: string, data: Record<string, unknown>): void {
    const id = `m${nextId++}`;
    inTransit.set(id, { id, from, to, action, data });
  }

  function handle(msg: Message): void {
    const self = nodes.get(msg.to);
    if (!self) return;
    if (msg.action === 'RequestVote') {
      const candidate = msg.data.from;
      const term = msg.data.term;
      if (typeof candidate !== 'string' || term !== 1 || !nodes.has(candidate) || candidate === msg.to) return;
      let granted = false;
      if (self.term === 0) {
        self.term = 1;
        self.role = 'follower';
        self.votedFor = candidate;
        granted = true;
      } else if (self.term === 1) {
        granted = self.role === 'follower' && (self.votedFor === null || self.votedFor === candidate);
        if (granted) self.votedFor = candidate;
      }
      send(msg.to, candidate, 'VoteReply', { term: 1, granted });
    } else if (msg.action === 'VoteReply') {
      if (self.role !== 'candidate' || msg.data.term !== self.term || msg.data.granted !== true) return;
      self.votes.add(msg.from);
      if (self.votes.size >= MAJORITY) self.role = 'leader';
    }
  }

  const host: Host = {
    async inFlight() {
      return [...inTransit.values()].map((m) => ({ ...m, data: { ...m.data } }));
    },
    async deliver(id: string) {
      const msg = inTransit.get(id);
      if (!msg) return;
      inTransit.delete(id);
      handle(msg);
    },
    async deliverAll() {
      while (inTransit.size > 0) {
        const [id, msg] = inTransit.entries().next().value as [string, Message];
        inTransit.delete(id);
        handle(msg);
      }
    },
    async timeout(node: string): Promise<Outcome> {
      const self = nodes.get(node);
      if (!self) return { ok: false, reason: `unknown node: ${node}` };
      if (self.role !== 'follower' || self.term !== 0) {
        return { ok: false, reason: `${node} cannot start an election: it is a ${self.role} in term ${self.term}` };
      }
      self.role = 'candidate';
      self.term = 1;
      self.votedFor = node;
      self.votes = new Set([node]);
      for (const other of NODE_IDS) {
        if (other !== node) send(node, other, 'RequestVote', { from: node, term: 1 });
      }
      return { ok: true };
    },
    async node(node: string) {
      const self = nodes.get(node);
      if (!self) return null;
      return { role: self.role, term: self.term, votedFor: self.votedFor };
    },
  };
  return host;
};

export default createHost;
EOF
cat > test/host.test.ts <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import create from '../src/host.impl.ts';

test('single election', async () => {
  const h = await create();
  assert.deepEqual(await h.timeout('n0'), { ok: true });
  assert.equal((await h.timeout('n0')).ok, false);
  assert.equal((await h.timeout('x')).ok, false);
  assert.equal((await h.inFlight()).length, 2);
  await h.deliverAll();
  assert.deepEqual(await h.node('n0'), { role: 'leader', term: 1, votedFor: 'n0' });
  assert.deepEqual(await h.node('n1'), { role: 'follower', term: 1, votedFor: 'n0' });
  assert.equal(await h.node('zz'), null);
  assert.equal((await h.timeout('n1')).ok, false);
});

test('random orders: safety', async () => {
  for (let i = 0; i < 2000; i++) {
    const h = await create();
    const starters = NODES().filter(() => Math.random() < 0.7);
    for (const s of starters) await h.timeout(s);
    for (;;) {
      const f = await h.inFlight();
      if (!f.length) break;
      await h.deliver(f[Math.floor(Math.random() * f.length)].id);
      if (Math.random() < 0.2) { const n = NODES()[Math.floor(Math.random()*3)]; await h.timeout(n); }
    }
    const views = await Promise.all(NODES().map((n) => h.node(n)));
    const leaders = views.filter((v) => v!.role === 'leader');
    assert.ok(leaders.length <= 1);
    for (const v of views) if (v!.term === 1) assert.ok(v!.votedFor);
  }
});
function NODES() { return ['n0', 'n1', 'n2']; }
EOF
