test('random orders with crashes: safety', async () => {
  const pick = () => NODES[Math.floor(Math.random() * 3)];
  for (let i = 0; i < 3000; i++) {
    const h = await create();
    const everLeader = new Set<string>();
    const everVoted = new Map<string, string>();
    const check = async () => {
      for (const n of NODES) {
        const v = (await h.node(n))!;
        if (v.role === 'leader') everLeader.add(n);
        if (v.votedFor !== null) {
          const prev = everVoted.get(n);
          assert.ok(prev === undefined || prev === v.votedFor, 'voted twice');
          everVoted.set(n, v.votedFor);
        }
        if (v.leader !== null) everLeader.add(v.leader);
      }
      assert.ok(everLeader.size <= 1, 'two leaders');
      for (const l of everLeader) assert.ok([...everVoted.values()].filter((x) => x === l).length >= 2);
    };
    for (let step = 0; step < 40; step++) {
      const r = Math.random();
      const f = await h.inFlight();
      if (r < 0.15) await h.timeout(pick());
      else if (r < 0.2) await h.giveUp(pick());
      else if (r < 0.28) await h.crash(pick());
      else if (r < 0.36) await h.recover(pick());
      else if (f.length) await h.deliver(f[Math.floor(Math.random() * f.length)].id);
      await check();
    }
    await h.deliverAll();
    await check();
  }
});

