import { test } from 'node:test';
import assert from 'node:assert/strict';
import create from '../src/host.impl.ts';

const NODES = ['n0', 'n1', 'n2'];

test('single election', async () => {
  const h = await create();
  assert.deepEqual(await h.timeout('n0'), { ok: true });
  assert.equal((await h.timeout('n0')).ok, false);
  assert.equal((await h.timeout('x')).ok, false);
  assert.equal((await h.inFlight()).length, 2);
  await h.deliverAll();
  assert.deepEqual(await h.node('n0'), { role: 'leader', term: 1, votedFor: 'n0', leader: 'n0' });
  assert.deepEqual(await h.node('n1'), { role: 'follower', term: 1, votedFor: 'n0', leader: 'n0' });
  assert.equal(await h.node('zz'), null);
  assert.equal((await h.timeout('n1')).ok, false);
});

test('random orders: safety', async () => {
  for (let i = 0; i < 2000; i++) {
    const h = await create();
    for (const s of NODES) if (Math.random() < 0.7) await h.timeout(s);
    for (;;) {
      const f = await h.inFlight();
      if (!f.length) break;
      await h.deliver(f[Math.floor(Math.random() * f.length)].id);
      if (Math.random() < 0.2) await h.timeout(NODES[Math.floor(Math.random() * 3)]);
      if (Math.random() < 0.1) await h.giveUp(NODES[Math.floor(Math.random() * 3)]);
    }
    const views = await Promise.all(NODES.map((n) => h.node(n)));
    const leaders = views.filter((v) => v!.role === 'leader');
    assert.ok(leaders.length <= 1);
    for (const l of leaders) {
      const name = NODES[views.indexOf(l)];
      assert.ok(views.filter((v) => v!.votedFor === name).length >= 2);
      for (const v of views) assert.equal(v!.leader, name);
      assert.ok(!views.some((v) => v!.role === 'candidate'));
    }
    if (!leaders.length) for (const v of views) assert.equal(v!.leader, null);
  }
});

test('giveUp', async () => {
  const h = await create();
  assert.equal((await h.giveUp('n0')).ok, false);
  assert.equal((await h.giveUp('zz')).ok, false);
  await h.timeout('n0');
  assert.deepEqual(await h.giveUp('n0'), { ok: true });
  assert.equal((await h.giveUp('n0')).ok, false);
  assert.equal((await h.timeout('n0')).ok, false);
  await h.timeout('n1');
  await h.deliverAll();
  // n2 votes for n0 (whose replies are now ignored); n1 gets no vote from n0 or n2.
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n0', leader: null });
  assert.deepEqual(await h.node('n1'), { role: 'candidate', term: 1, votedFor: 'n1', leader: null });
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: 'n0', leader: null });

  const g = await create();
  await g.timeout('n0');
  await g.timeout('n1');
  await g.giveUp('n0');
  const toN2 = (await g.inFlight()).find((m) => m.from === 'n1' && m.to === 'n2')!;
  await g.deliver(toN2.id);
  await g.deliverAll();
  assert.deepEqual(await g.node('n1'), { role: 'leader', term: 1, votedFor: 'n1', leader: 'n1' });
  assert.deepEqual(await g.node('n0'), { role: 'follower', term: 1, votedFor: 'n0', leader: 'n1' });
  assert.equal((await g.giveUp('n1')).ok, false);
});

test('Leader message: term-0 follower joins without voting; candidate steps down', async () => {
  const h = await create();
  await h.timeout('n0');
  await h.timeout('n2');
  const f = await h.inFlight();
  const toN1 = f.find((m) => m.from === 'n0' && m.to === 'n1')!;
  await h.deliver(toN1.id);
  const reply = (await h.inFlight()).find((m) => m.action === 'VoteReply')!;
  await h.deliver(reply.id);
  assert.equal((await h.node('n0'))!.role, 'leader');
  const leaderMsgs = (await h.inFlight()).filter((m) => m.action === 'Leader');
  assert.equal(leaderMsgs.length, 2);
  assert.deepEqual(leaderMsgs.find((m) => m.to === 'n2')!.data, { from: 'n0', term: 1 });
  for (const m of leaderMsgs) await h.deliver(m.id);
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: 'n2', leader: 'n0' });

  const g = await create();
  await g.timeout('n0');
  const m01 = (await g.inFlight()).find((m) => m.to === 'n1')!;
  await g.deliver(m01.id);
  await g.deliver((await g.inFlight()).find((m) => m.action === 'VoteReply')!.id);
  await g.deliver((await g.inFlight()).find((m) => m.action === 'Leader' && m.to === 'n2')!.id);
  assert.deepEqual(await g.node('n2'), { role: 'follower', term: 1, votedFor: null, leader: 'n0' });
  assert.equal((await g.timeout('n2')).ok, false);
});
